using System.Text;using System.Text.Json;namespace QuantForge.Core;public sealed class AndroidResearchSessionSummaryFileStore{private readonly string _root;private static readonly JsonSerializerOptions Options=new(){WriteIndented=true};public AndroidResearchSessionSummaryFileStore(string root){if(string.IsNullOrWhiteSpace(root))throw new ArgumentException("A session summary root is required.",nameof(root));_root=Path.GetFullPath(root);}public string Save(AndroidResearchSessionSummary value){ArgumentNullException.ThrowIfNull(value);if(value.CanSubmitOrders)throw new InvalidOperationException("Research session summaries cannot grant order authority.");var dir=Path.Combine(_root,value.SessionFingerprint);var path=Path.Combine(dir,"android-research-session.json");Directory.CreateDirectory(dir);var json=JsonSerializer.Serialize(value,Options);if(File.Exists(path)&&!string.Equals(File.ReadAllText(path,Encoding.UTF8),json,StringComparison.Ordinal))throw new InvalidOperationException("Research session fingerprint collision contains different content.");File.WriteAllText(path,json,new UTF8Encoding(false));return path;}public AndroidResearchSessionSummary Load(string fingerprint){var path=Path.Combine(_root,Safe(fingerprint),"android-research-session.json");var value=JsonSerializer.Deserialize<AndroidResearchSessionSummary>(File.ReadAllText(path,Encoding.UTF8),Options)??throw new InvalidOperationException("Android research session JSON is invalid.");if(value.SessionFingerprint!=fingerprint)throw new InvalidOperationException("Stored research session identity does not match its key.");if(value.CanSubmitOrders)throw new InvalidOperationException("Persisted research session grants order authority.");return value;}private static string Safe(string value){if(string.IsNullOrWhiteSpace(value)||value.Any(ch=>!(char.IsLetterOrDigit(ch)||ch is '-' or '_')))throw new ArgumentException("Unsafe session fingerprint.",nameof(value));return value;}}
